import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788343875000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>FRESHRSS_URL</code></td><td>yes</td><td>—</td><td>Root URL of the FreshRSS instance, e.g. <code>https://rss.example.com</code></td></tr><tr><td><code>FRESHRSS_USER</code></td><td>yes</td><td>—</td><td>FreshRSS user name</td></tr><tr><td><code>FRESHRSS_API_PASSWORD</code></td><td>yes</td><td>—</td><td>The API password from Settings → Profile → API management</td></tr><tr><td><code>FRESHRSS_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>1</code>, <code>true</code> or <code>yes</code> registers only the eight read tools</td></tr><tr><td><code>FRESHRSS_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts a self-signed certificate, scoped to this connection</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><p>There is no configuration file and no command-line flag; these are the whole surface. The reasoning behind each is in <a href="/guide/configuration">Configuration</a>.</p><h2 id="validation-at-startup" tabindex="-1">Validation at startup <a class="header-anchor" href="#validation-at-startup" aria-label="Permalink to “Validation at startup”">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>A required variable is missing</td><td>Warning; the server starts and lists tools</td></tr><tr><td><code>FRESHRSS_URL</code> does not parse</td><td><strong>Exit 1</strong> (the value is logged with credentials redacted)</td></tr><tr><td><code>FRESHRSS_URL</code> scheme is not <code>http</code>/<code>https</code></td><td><strong>Exit 1</strong></td></tr><tr><td><code>FRESHRSS_URL</code> contains <code>user:password@</code></td><td><strong>Exit 1</strong></td></tr><tr><td><code>FRESHRSS_URL</code> is plain http to a non-loopback host</td><td>Warning about the unencrypted API password</td></tr><tr><td><code>FRESHRSS_INSECURE_TLS=true</code></td><td>Warning that certificate validation is relaxed</td></tr><tr><td><code>ELICITATION</code> is neither <code>true</code> nor <code>false</code></td><td><strong>Exit 1</strong>, naming both valid values</td></tr><tr><td><code>ELICITATION=false</code></td><td>One line saying guarded tools fall back to the two-call token</td></tr></tbody></table><p>A missing credential is deliberately not fatal: the server must be able to complete the MCP handshake and answer <code>tools/list</code> without one, so registries and sandbox inspectors can introspect it. Every tool call then fails with the setup instructions. A malformed URL <em>is</em> fatal — that one could send the API password to the wrong host.</p><p>All diagnostics go to <strong>stderr</strong>, which is where MCP stdio servers must log — stdout carries the protocol.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p><strong>Optional</strong>, default <code>true</code>. Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable on this page:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> <code>1</code>, <code>off</code> or a typo stop the server with exit code 1 rather than falling back to the default. It is the only variable of this family that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively, so <code>False</code> and <code>false</code> both work — the strictness is about which words count, not about their shape. It is read <em>after</em> <code>FRESHRSS_API_PASSWORD</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the password sitting there for a crash reporter.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li><code>FRESHRSS_READ_ONLY</code> accepts <code>1</code>, <code>true</code> or <code>yes</code>, in any casing and with surrounding whitespace ignored. Anything else leaves it off. It is read tolerantly because it turns a protection <strong>on</strong>: a value the operator meant as yes but spelled differently would otherwise register every write tool and say nothing about it.</li><li><code>FRESHRSS_INSECURE_TLS</code> needs the exact string <code>true</code>; <code>1</code> and <code>yes</code> leave it off. Read strictly for the mirror-image reason — it turns a protection <strong>off</strong>, so a value nobody spelled exactly has to leave certificate validation on.</li><li>Trailing slashes on <code>FRESHRSS_URL</code> are stripped.</li><li>The API path <code>/api/greader.php</code> is appended automatically — do not include it.</li><li><code>FRESHRSS_API_PASSWORD</code> is <strong>deleted from <code>process.env</code></strong> once the configuration has been read, on every path including the ones that then exit. It would otherwise stay readable by child processes and in <code>/proc/&lt;pid&gt;/environ</code>.</li><li>Requests use a 30-second timeout (120 seconds for <code>subscribe_feed</code> and <code>import_opml</code>, which make FreshRSS fetch from the internet first) and refuse to follow redirects.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><p>Not configurable, but they bound every response:</p><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Articles per listing</td><td>100 (default 20)</td></tr><tr><td>Ids per <code>get_articles</code></td><td>20</td></tr><tr><td>Articles per <code>mark_articles</code></td><td>100</td></tr><tr><td>Article text per article</td><td>20 000 characters (default 2000)</td></tr><tr><td>Excerpt length</td><td>300 characters</td></tr><tr><td>Article text per response</td><td>60 000 characters</td></tr><tr><td>Serialised tool result</td><td>400 000 characters</td></tr><tr><td>OPML export</td><td>200 000 characters</td></tr><tr><td>OPML import</td><td>900 000 characters</td></tr><tr><td>Confirmation token lifetime</td><td>5 minutes, single use</td></tr></tbody></table><p>The OPML import limit sits below the 1 048 576 bytes FreshRSS reads from <code>php://input</code> — beyond that it truncates silently, which would arrive as malformed XML.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>FRESHRSS_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>FRESHRSS_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>FRESHRSS_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>list_feeds</code>, <code>list_categories</code>, <code>get_unread_counts</code>, <code>list_articles</code>, <code>get_articles</code>, <code>mark_articles</code>, <code>mark_all_as_read</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>FRESHRSS_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};